@triton.jit
def _dot_kernel(
    a_ptr,
    b_ptr,
    o_ptr,
    part_ptr,
    K,
    CHUNK,
    SA,
    SB,
    SPLIT: tl.constexpr,
    ACC: tl.constexpr,
    OUT_DT: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if SPLIT > 1:
        c_start = pid * CHUNK
        c_end = tl.minimum(K, c_start + CHUNK)
    else:
        c_start = 0
        c_end = K
    offs = tl.arange(0, BLOCK)
    acc = tl.zeros((BLOCK,), dtype=ACC)
    for k0 in range(c_start, c_end, BLOCK):
        kk = k0 + offs
        m = kk < K
        av = tl.load(a_ptr + kk * SA, mask=m, other=0).to(ACC)
        bv = tl.load(b_ptr + kk * SB, mask=m, other=0).to(ACC)
        acc += av * bv
    s = tl.sum(acc, axis=0)
    if SPLIT > 1:
        tl.store(part_ptr + pid, s)
    else:
        tl.store(o_ptr, s.to(OUT_DT))


@triton.jit
def _reduce_kernel(
    x_ptr,
    o_ptr,
    part_ptr,
    ONUMEL,
    CPROD,
    CHUNK,
    ND: tl.constexpr,
    ODIMS: tl.constexpr,
    ODIVS: tl.constexpr,
    SX: tl.constexpr,
    NC: tl.constexpr,
    CDIMS: tl.constexpr,
    CDIVS: tl.constexpr,
    SXC: tl.constexpr,
    SPLIT: tl.constexpr,
    ACC: tl.constexpr,
    OUT_DT: tl.constexpr,
    BLOCK_O: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    pid = tl.program_id(0)
    if SPLIT > 1:
        pid_s = pid % SPLIT
        pid_o = pid // SPLIT
        c_start = pid_s * CHUNK
        c_end = tl.minimum(CPROD, c_start + CHUNK)
    else:
        pid_s = 0
        pid_o = pid
        c_start = 0
        c_end = CPROD
    offs = pid_o * BLOCK_O + tl.arange(0, BLOCK_O)
    m_o = offs < ONUMEL
    ooff = tl.zeros((BLOCK_O,), dtype=tl.int32)
    for i in tl.static_range(ND):
        ooff += ((offs // ODIVS[i]) % ODIMS[i]) * SX[i]
    oc = tl.arange(0, BLOCK_C)
    accv = tl.zeros((BLOCK_O, BLOCK_C), dtype=ACC)
    for c0 in range(c_start, c_end, BLOCK_C):
        cc = c0 + oc
        coff = tl.zeros((BLOCK_C,), dtype=tl.int32)
        for i in tl.static_range(NC):
            coff += ((cc // CDIVS[i]) % CDIMS[i]) * SXC[i]
        m = (cc < c_end)[None, :] & m_o[:, None]
        v = tl.load(x_ptr + ooff[:, None] + coff[None, :], mask=m, other=0)
        accv += v.to(ACC)
    acc = tl.sum(accv, axis=1)
    if SPLIT > 1:
        tl.store(part_ptr + pid_s * ONUMEL + offs, acc, mask=m_o)
    else:
        tl.store(o_ptr + offs, acc.to(OUT_DT), mask=m_o)


