def _gemm_affine_kernel(
    a_ptr,
    b_ptr,
    o_ptr,
    M,
    N,
    K,
    NBM,
    NBN,
    DTC,
    SA_B: tl.constexpr,
    SA_M: tl.constexpr,
    SA_K: tl.constexpr,
    SB_B: tl.constexpr,
    SB_K: tl.constexpr,
    SB_N: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_N: tl.constexpr,
    EVEN_K: tl.constexpr,
    USE_DOT: tl.constexpr,
    ACC: tl.constexpr,
    IN_DT: tl.constexpr,
    OUT_DT: tl.constexpr,
):
    """Single-label-per-group batched GEMM.

    Every group stride is a compile-time constant, so Triton can prove the
    affine/contiguous access pattern, vectorise the operand loads and drop the
    mask tensors entirely for evenly divisible shapes.  This keeps the
    integer/BFU pipes idle, which the profile of the generic kernel showed to
    be the dominant cost.
    """
    pid = tl.program_id(0)
    pid_n = pid % NBN
    tmp = pid // NBN
    pid_m = tmp % NBM
    pid_b = tmp // NBM
    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    offs_k = tl.arange(0, BLOCK_K)
    a_ptrs = a_ptr + pid_b * SA_B + offs_m[:, None] * SA_M + offs_k[None, :] * SA_K
    b_ptrs = b_ptr + pid_b * SB_B + offs_k[:, None] * SB_K + offs_n[None, :] * SB_N
    m_mask = offs_m < M
    n_mask = offs_n < N
    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=ACC)
    for k0 in range(0, K, BLOCK_K):
        if EVEN_M and EVEN_K:
            av = tl.load(a_ptrs)
        elif EVEN_K:
            av = tl.load(a_ptrs, mask=m_mask[:, None], other=0)
        else:
            av = tl.load(
                a_ptrs, mask=m_mask[:, None] & (k0 + offs_k < K)[None, :], other=0
            )
        if EVEN_N and EVEN_K:
            bv = tl.load(b_ptrs)
        elif EVEN_K:
            bv = tl.load(b_ptrs, mask=n_mask[None, :], other=0)
        else:
            bv = tl.load(
                b_ptrs, mask=(k0 + offs_k < K)[:, None] & n_mask[None, :], other=0
            )
        av = av.to(IN_DT)
        bv = bv.to(IN_DT)
        if USE_DOT:
            acc = tl.dot(av, bv, acc)
        else:
            acc += tl.sum(av[:, :, None].to(ACC) * bv[None, :, :].to(ACC), axis=1)
